//! The character properties CPython 3.12 answers from its Unicode database (15.0.0): the
//! decimal digit value `float(str)` and `int(str)` accept, `str.isspace()` and
//! `str.isprintable()`. The tables are generated by `tools/gen_unicode.py` from the interpreter
//! itself; its `--check` under Windows and Linux CPython proves them.

use crate::unicode_tables::{DECIMAL, NOT_PRINTABLE, SPACE};

pub use crate::unicode_tables::UNICODE_VERSION;

fn in_ranges(ranges: &[(u32, u32)], code: u32) -> bool {
    let index = ranges.partition_point(|&(_, last)| last < code);
    ranges.get(index).is_some_and(|&(first, _)| first <= code)
}

/// `Py_UNICODE_TODECIMAL(c)` when it is a digit: the value of a category Nd character.
pub fn decimal_digit(c: char) -> Option<u8> {
    let code = c as u32;
    let index = DECIMAL.partition_point(|&(_, last, _)| last < code);
    let &(first, _, value) = DECIMAL.get(index)?;
    (first <= code).then(|| value + (code - first) as u8)
}

/// `c.isspace()`.
pub fn is_space(c: char) -> bool {
    in_ranges(SPACE, c as u32)
}

/// `c.isprintable()`: false for the characters `repr(str)` escapes.
pub fn is_printable(c: char) -> bool {
    !in_ranges(NOT_PRINTABLE, c as u32)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn tables_are_sorted_and_disjoint() {
        for table in [SPACE, NOT_PRINTABLE] {
            assert!(table.iter().all(|&(a, b)| a <= b));
            assert!(table.windows(2).all(|w| w[0].1 < w[1].0));
        }
        assert!(
            DECIMAL
                .iter()
                .all(|&(a, b, v)| a <= b && u32::from(v) + (b - a) <= 9)
        );
        assert!(DECIMAL.windows(2).all(|w| w[0].1 < w[1].0));
    }

    #[test]
    fn known_characters() {
        assert_eq!(decimal_digit('7'), Some(7));
        assert_eq!(decimal_digit('\u{0661}'), Some(1));
        assert_eq!(decimal_digit('\u{1D7FF}'), Some(9));
        assert_eq!(decimal_digit('\u{00B2}'), None); // superscript two: a digit, not decimal
        assert_eq!(decimal_digit('\u{00BD}'), None);
        assert!(is_space('\u{1F}') && is_space('\u{3000}') && !is_space('\u{180E}'));
        assert!(!is_space('\u{200B}'));
        assert!(is_printable(' ') && is_printable('é'));
        assert!(!is_printable('\u{2066}') && !is_printable('\u{A0}') && !is_printable('\u{378}'));
    }
}
